fn str_at(xs: List[Str], i: Int) -> Str {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return ""
        }
    }
}

fn split_on(s: Str, sep: Str) -> List[Str] {
    var out: List[Str] = []
    var cur = ""
    for c in s.chars() {
        if c == sep {
            out = out.push(cur)
            cur = ""
        } else {
            cur = cur + c
        }
    }
    out = out.push(cur)
    return out
}

fn all_digits(s: Str) -> Bool {
    var ok = s != ""
    for c in s.chars() {
        if not (c >= "0" and c <= "9") {
            ok = false
        }
    }
    return ok
}

fn num_of(s: Str) -> Int {
    var v = 0
    for c in s.chars() {
        if c == "0" {
            v = v * 10
        } else if c == "1" {
            v = v * 10 + 1
        } else if c == "2" {
            v = v * 10 + 2
        } else if c == "3" {
            v = v * 10 + 3
        } else if c == "4" {
            v = v * 10 + 4
        } else if c == "5" {
            v = v * 10 + 5
        } else if c == "6" {
            v = v * 10 + 6
        } else if c == "7" {
            v = v * 10 + 7
        } else if c == "8" {
            v = v * 10 + 8
        } else {
            v = v * 10 + 9
        }
    }
    return v
}

